{id="t0127-33",kind="written",pieces={"notepad"},where={{place="mapNamed",spot="ground",lean="agricultural",rival="containment"}},title="Second skull, rain-barrel sample",body="Receipt back at the second skull: one rain-barrel sample, paid cash. The barrel stood downwind of the experimental orchard.",anchor={map="WorldStashMap18",note=32}},
{id="t0127-34",kind="written",pieces={"receipt"},where={{place="mapNamed",spot="ground",lean="agricultural",rival="containment"}},title="Third skull, birds under the wire",body="Diary line at the third skull: birds dropped beneath the plot wire after dawn spraying. The crew buried them before opening the gate.",anchor={map="WorldStashMap18",note=33}},
{id="t0127-35",kind="written",pieces={"photograph"},where={{place="mapNamed",spot="ground",lean="agricultural",rival="containment"}},title="Fourth skull, missing drum weight",body="Warehouse note at the fourth skull: the returned treatment drum weighed nine pounds less than dispatch. Its seal appeared untouched.",anchor={map="WorldStashMap18",note=34}},
{id="t0127-36",kind="written",pieces={"notebook"},where={{place="mapNamed",spot="ground",lean="agricultural",rival="containment"}},title="Fifth skull, milk poured away",body="Farm notebook at the fifth skull: pour away milk from the test pasture until told otherwise. The instruction arrived before the cattle looked ill.",anchor={map="WorldStashMap18",note=35}},
{id="t0127-37",kind="written",pieces={"letter"},where={{place="mapNamed",spot="ground",lean="agricultural",rival="containment"}},title="Sixth skull, blackened bean leaves",body="Photograph back at the sixth skull: bean leaves blackened in the shape of yesterday’s spray fan. The roots remained pale and firm.",anchor={map="WorldStashMap18",note=36}},
{id="t0127-38",kind="written",pieces={"diary"},where={{place="mapNamed",spot="ground",lean="agricultural",rival="containment"}},title="Seventh skull, final field count",body="Torn ledger at the seventh skull: the final field count omits two applicators and one sample case. Their truck is still marked returned.",anchor={map="WorldStashMap18",note=37}},
